cat > studio-quota.test.mjs <<'EOF'
import test from "node:test";
import assert from "node:assert/strict";
import {planner, apply} from "./replay.mjs";
import {Ledger} from "./common/ledger.mjs";
import {bookStudio} from "./services/studio.mjs";

const catalog = () => ({default:5, studios:new Map([["orchid",8], ["iris",3]])});
const book = (id, units, extra = {}) => ({service:"studio", action:"book", tenant:"orchid",
  day:"2025-04-02", id, units, ...extra});
const renew = (previous, id, extra = {}) => ({service:"studio", action:"renew", previous,
  id, day:"2025-05-02", ...extra});

test("direct Studio adapter applies allocations without mutating the catalog or ledger policy", () => {
  const config = catalog();
  const ledger = new Ledger(config);
  assert.deepEqual(bookStudio(ledger, book("first", 7), config),
    {status:"booked", id:"first", remaining:1});
  assert.equal(config.default, 5);
  assert.equal(ledger.catalog, config);
  assert.equal(ledger.usage("orchid", "2025-04-02"), 7);
});

test("allocations, default fallback, and tenant/day accounting", () => {
  const dispatch = planner(catalog());
  assert.equal(dispatch(book("a", 7)).status, "booked");
  assert.deepEqual(dispatch(book("b", 2)), {status:"full", id:"b", remaining:1});
  assert.equal(dispatch(book("c", 1)).remaining, 0);
  assert.equal(dispatch(book("other-day", 8, {day:"2025-04-03"})).remaining, 0);
  assert.equal(dispatch(book("low", 4, {tenant:"iris"})).status, "full");
  assert.equal(dispatch(book("low", 3, {tenant:"iris"})).remaining, 0);
  assert.equal(dispatch(book("default", 6, {tenant:"lily"})).status, "full");
  assert.equal(dispatch(book("default", 5, {tenant:"lily"})).remaining, 0);
  assert.equal(dispatch(book("archive", 6, {service:"archive"})).status, "full");
  assert.equal(dispatch(book("archive", 5, {service:"archive"})).remaining, 0);
});

test("direct bookings and renewals share admission and existing replay semantics", () => {
  const dispatch = planner(catalog());
  const request = book("original", 7);
  assert.equal(dispatch(request).status, "booked");
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units:8}).status, "conflict");
  assert.equal(dispatch(renew("original", "next")).remaining, 1);
  assert.equal(dispatch(renew("original", "next")).status, "replay");
  assert.equal(dispatch(renew("original", "excess", {units:2})).status, "full");
  assert.equal(dispatch(book("direct-next", 1, {day:"2025-05-02"})).remaining, 0);
  assert.equal(dispatch({service:"studio", action:"cancel", id:"next"}).status, "cancelled");
  assert.equal(dispatch(renew("original", "next")).status, "cancelled");
  assert.equal(dispatch(renew("original", "replacement")).remaining, 0);
  assert.equal(dispatch(renew("next", "missing")).status, "missing");
  assert.equal(dispatch(renew("absent", "missing")).status, "missing");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"next"}).status, "replay");
  assert.equal(apply(dispatch, book("bad", 0)).status, "invalid");
});

test("renewals use inherited tenant limits, including fallback and lower quotas", () => {
  const dispatch = planner(catalog());
  for (const [tenant, cap] of [["iris",3], ["lily",5]]) {
    const id = tenant + "-old";
    assert.equal(dispatch(book(id, cap, {tenant})).status, "booked");
    assert.equal(dispatch(renew(id, tenant + "-too-big", {units:cap + 1})).status, "full");
    assert.equal(dispatch(renew(id, tenant + "-new")).remaining, 0);
  }
  assert.equal(dispatch(book("archive-old", 5, {service:"archive"})).status, "booked");
  assert.equal(dispatch(renew("archive-old", "archive-new", {service:"archive", units:6})).status, "full");
});

test("imports bypass admission but count toward subsequent bookings", () => {
  const dispatch = planner(catalog());
  assert.equal(dispatch(book("backfill", 10, {action:"import"})).status, "imported");
  assert.equal(dispatch(book("backfill", 10)).status, "replay");
  assert.deepEqual(dispatch(book("new", 1)), {status:"full", id:"new", remaining:0});
  dispatch({service:"studio", action:"cancel", id:"backfill"});
  assert.equal(dispatch(book("new", 8)).remaining, 0);
});
